def rol(value, shift, bits=8):
    shift %= bits
    mask = (1 << bits) -1
    return (value << shift | value >> (bits - shift)) & mask

with open("program.bin","rb") as prog, open("output.bin","rb") as out:
    prog = list(reversed(prog.read()))
    out = list(out.read())

    for x in range(0, len(prog), 2):
        if (prog[x+1]) == 3:
            for y in range(len(out)):
                out[y] = rol(out[y],prog[x+0])
        elif prog[x+1] == 1:
            for y in range(len(out)):
                out[y] = (out[y] - prog[x+0]) & 255
        elif prog[x+1] == 2:
            for y in range(len(out)):
                out[y] ^= prog[x+0]
        else:
            break

    for x in out:
        print(chr(x),end="")

